-		retval = tsi148_dma_set_vme_src_attributes(tsi148_bridge->parent,
-							   &entry->descriptor.dsat,
-							   vme_attr->aspace,
-							   vme_attr->cycle,
-							   vme_attr->dwidth);
-		if (retval < 0)
-			goto err_source;
-		break;
